import math

def count_binary_seq(n):
    return math.comb(2 * n, n)

def highest_Power_of_2(n):
    if n <= 0:
        return 0
    power = 1
    while power * 2 <= n:
        power *= 2
    return power

def find_lucas(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 2
    if n == 1:
        return 1

    prev, curr = 2, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr

def max_product(arr):
    if not arr:
        return 0

    max_ending = min_ending = best = arr[0]

    for i in range(1, len(arr)):
        x = arr[i]

        if x > arr[i - 1]:
            prod1 = max_ending * x
            prod2 = min_ending * x
            max_ending = max(x, prod1, prod2)
            min_ending = min(x, prod1, prod2)
        else:
            max_ending = min_ending = x

        best = max(best, max_ending)

    return best

def first_Digit(n):
    n = abs(int(n))
    while n >= 10:
        n //= 10
    return n

def find_Odd_Pair(arr, n):
    odd_count = 0
    even_count = 0

    for num in arr[:n]:
        if num % 2:
            odd_count += 1
        else:
            even_count += 1

    return odd_count * even_count

def unique_product(numbers):
    product = 1
    seen = set()

    for number in numbers:
        if number not in seen:
            product *= number
            seen.add(number)

    return product

