                result.append(item)
                seen.add(item)

        for item in tup2:
            if item not in set1 and item not in seen:
                result.append(item)
                seen.add(item)

        return tuple(result)

    except TypeError:
        result = []

        for item in tup1:
            if item not in tup2 and item not in result:
                result.append(item)

        for item in tup2:
            if item not in tup1 and item not in result:
                result.append(item)

        return tuple(result)

