import math

def count_binary_seq(n):
    return math.comb(2 * n, n)

def highest_Power_of_2(n):
    if n < 1:
        return 0
    return 1 << (n.bit_length() - 1)

def find_lucas(n):
    if n == 0:
        return 2
    if n == 1:
        return 1

    prev, curr = 2, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr

def check_distinct(test_tup):
    try:
        return len(test_tup) == len(set(test_tup))
    except TypeError:
        seen = []
        for item in test_tup:
            if item in seen:
                return False
            seen.append(item)
        return True

def max_product(arr):
    if not arr:
        return 0

    current_product = arr[0]
    max_product_value = arr[0]

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            current_product *= arr[i]
        else:
            current_product = arr[i]

        if current_product > max_product_value:
            max_product_value = current_product

    return max_product_value

def find_Odd_Pair(arr, n):
    odd_count = 0
    even_count = 0

    for num in arr[:n]:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return odd_count * even_count

