    )

def split_Arr(arr, n):
    if not arr:
        return []
    n %= len(arr)
    return arr[n:] + arr[:n]

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    return xor != 0 and (xor & (xor - 1)) == 0

