def get_median(list1, list2, n):
    if n <= 0:
        return None

    i = j = 0
    merged = []

    while i < n and j < n:
        if list1[i] <= list2[j]:
            merged.append(list1[i])
            i += 1
        else:
            merged.append(list2[j])
            j += 1

    while i < n:
        merged.append(list1[i])
        i += 1

    while j < n:
        merged.append(list2[j])
        j += 1

    return (merged[n - 1] + merged[n]) / 2.0

def find_first_occurrence(arr, target):
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            result = mid
            right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return result

from itertools import combinations

def find_combinations(test_list):
    return [tuple(a + b for a, b in zip(t1, t2)) for t1, t2 in combinations(test_list, 2)]

def _sum(arr):
    total = 0
